// Verify HMAC
const crypto = require('crypto');
const secret = 'secret_123';

const headers = $input.item.json.headers;
const signatureHeader = headers['x-unifit-signature'];
const body = $input.item.json.body;

if (!signatureHeader) {
  throw new Error('401 Unauthorized: Missing Signature Header');
}

// El body viene como objeto JSON, necesitamos stringify para el hash
// Nota: Esto asume que el orden de las claves coincide. En prod usar 'RAW BODY'
const payloadString = JSON.stringify(body);

const computedSignature = crypto.createHmac('sha256', secret)
  .update(payloadString)
  .digest('hex');

// Comparación simple (en prod usar timingSafeEqual)
if (signatureHeader !== computedSignature) {
   // Descomentar para hacer cumplir seguridad estricta
   // throw new Error(`403 Forbidden: Invalid Signature. Expected ${computedSignature}, got ${signatureHeader}`);

   // Por ahora logueamos warning
   console.log('HMAC Mismatch - Check JSON serialization order');
}

return { json: { ...body, _verification: 'passed' } };

const data = $input.item.json.data;

// Simulate Business Logic
// e.g., Generate a Ticket ID for Tours Paradise

const ticketId = 'TP-' + Math.floor(Math.random() * 10000);
const partnerName = 'Tours Paradise';

return {
  json: {
    action: 'provision_ticket',
    partner: partnerName,
    ticketId: ticketId,
    originalPaymentId: data.paymentId,
    forUser: data.userEmail,
    status: 'CONFIRMED',
    processedAt: new Date().toISOString()
  }
};
